// The page's own API client, over the signed-in session. One POST at a time,
// each carrying the CSRF token the last answer gave: the server spends a token
// on every check, so a refused one (403 {"error":"csrf"}) is refreshed from
// csrf.php once and the POST retried once. A lost session is SignedOut, read
// from the status (a redirect to the sign-in, a 401, or a 403 other than the
// CSRF refusal), never from the Content-Type. Every other failure is a ServerError naming the status.
import type { Fetch } from './load.ts';
import type { ChangeProof, LockedKeyring } from './unlock.ts';

export class SignedOut extends Error {}
export class NoKeyring extends Error {}
/** This studio already holds a notes key: the page never replaces it. */
export class KeyExists extends Error {}
/** A new passphrase was refused: the server's keyring no longer has the fingerprints this page re-locked. */
export class KeyChanged extends Error {}
/** fetch itself failed (offline, DNS, refused): a TypeError, as fetch rejects, but known to come from the network and not from this page's own code. */
export class NetworkError extends TypeError {}
/** The server answered 2xx, but not with what the page needs (no list, no keyring, not JSON). */
export class UnreadableAnswer extends Error {
  constructor() { super('The server sent an answer this page cannot read.'); }
}
/** The server answered, but with an error status. */
export class ServerError extends Error {
  readonly status: number;
  constructor(status: number) {
    super(`The server answered ${status}.`);
    this.status = status;
  }
}
export type RefusedReason = 'too_large' | 'over_quota' | 'full' | 'no_key' | 'bad_header' | 'unknown_key';
export const REFUSED_REASONS: readonly RefusedReason[] = ['too_large', 'over_quota', 'full', 'no_key', 'bad_header', 'unknown_key'];
/** `ai`: the fingerprints of the paired AI keys the server still lists as active; the page seals only to those of them the unlocked keyring holds. */
export interface KeyringAnswer { locked: LockedKeyring; session: string; ai: string[] }
/** Why a pairing try was refused (pair.php, keyring.php?pair=1). */
export type PairRefusal = 'wrong_code' | 'too_many' | 'no_key' | 'not_registered' | 'key_changed';
export const PAIR_REFUSALS: readonly PairRefusal[] = ['wrong_code', 'too_many', 'no_key', 'not_registered', 'key_changed'];
export interface ServerNote { id: string; size: number; arrived_at: number; picked_up_at: number | null }
/** `room`: with over_quota, the bytes the studio has left. */
export type UploadResult = { kind: 'sent'; id: string } | { kind: 'refused'; reason: RefusedReason; room?: number };
export interface PageApi {
  upload(bundle: Uint8Array<ArrayBuffer>): Promise<UploadResult>;
  /** Every note row the page can read, and how many rows it could not (they are left out, the rest still come). */
  list(): Promise<{ notes: ServerNote[]; unreadable: number }>;
  bytes(id: string): Promise<Uint8Array<ArrayBuffer>>;
  remove(id: string): Promise<number>;
  removeAll(): Promise<number>;
  /** The locked keyring, and the server's tag for this sign-in ('' when it gave none). */
  keyring(): Promise<KeyringAnswer>;
  /** Stores a keyring made on this page: `current` is its one key's fingerprint, and there are no previous keys. Rejects with KeyExists when the studio holds one already. */
  uploadKeyring(locked: LockedKeyring, current: string): Promise<void>;
  /** Stores the same keys locked under a new passphrase; the server takes it only when `current` and `previous` are the fingerprints it holds and `proof` is the current key's signature. KeyChanged when the fingerprints differ, NoKeyring when it holds none. */
  changeKeyring(locked: LockedKeyring, current: string, previous: string[], proof: ChangeProof): Promise<void>;
  /** One pairing try: the AI key's sealing key when `code` is its code, or why not. The server counts every try. */
  checkPairing(key: number, code: string): Promise<{ spki: string; fingerprint: string } | PairRefusal>;
  /** Stores the keyring locked again with the AI key added, as changeKeyring does, and marks the key paired; null, or why not. */
  pairKeyring(locked: LockedKeyring, current: string, previous: string[], proof: ChangeProof, pair: { key: number; code: string; fingerprint: string }): Promise<PairRefusal | null>;
  /** Deletes one draft of a piece, or every draft of it without a version; how many went. A draft that is already gone is a ServerError (404). */
  deleteDraft(piece: string, version?: number): Promise<number>;
}

type Reply = Awaited<ReturnType<Fetch>>;
type Data = Record<string, unknown>;
const NOTE_ID = /^[0-9a-f]{32}$/;
const encoder = new TextEncoder();

async function read(reply: Reply): Promise<Data> {
  try {
    const j: unknown = await reply.json();
    return typeof j === 'object' && j !== null && !Array.isArray(j) ? (j as Data) : {};
  } catch {
    return {};
  }
}
const signedOut = (reply: Reply, data: Data): boolean => reply.redirected || reply.status === 401 || (reply.status === 403 && data['error'] !== 'csrf');
const failed = (reply: Reply): ServerError => new ServerError(reply.status);
const isServerNote = (x: unknown): x is ServerNote => {
  const n = x as Partial<ServerNote> | null;
  return typeof n === 'object' && n !== null && typeof n.id === 'string' && NOTE_ID.test(n.id) && Number.isInteger(n.size)
    && Number.isInteger(n.arrived_at) && (n.picked_up_at === null || Number.isInteger(n.picked_up_at));
};
const noteId = (id: string): string => {
  if (!NOTE_ID.test(id)) throw new Error('Not a note id.');
  return id;
};

export function createApi(rawFetch: Fetch, csrf: string): PageApi {
  const fetch: Fetch = async (url, init) => {
    try {
      return await rawFetch(url, init);
    } catch (e) {
      throw e instanceof TypeError ? new NetworkError(e.message) : e;
    }
  };
  let token = csrf;
  let queue: Promise<unknown> = Promise.resolve();
  const get = async (url: string): Promise<{ reply: Reply; data: Data }> => {
    const reply = await fetch(url);
    const data = reply.redirected ? {} : await read(reply);
    if (signedOut(reply, data)) throw new SignedOut('Your sign-in ended.');
    return { reply, data };
  };
  const post = (url: string, type: string, body: Uint8Array<ArrayBuffer>): Promise<{ reply: Reply; data: Data }> => {
    const run = async (): Promise<{ reply: Reply; data: Data }> => {
      for (let attempt = 0; ; attempt++) {
        const reply = await fetch(url, { method: 'POST', headers: { 'X-CSRF': token, 'Content-Type': type }, body });
        const data = reply.redirected ? {} : await read(reply);
        if (typeof data['csrf'] === 'string') token = data['csrf'];
        if (reply.status === 403 && data['error'] === 'csrf' && attempt === 0) {
          const fresh = await get('csrf.php');
          if (!fresh.reply.ok || typeof fresh.data['csrf'] !== 'string') throw failed(fresh.reply);
          token = fresh.data['csrf'];
          continue;
        }
        if (signedOut(reply, data)) throw new SignedOut('Your sign-in ended.');
        return { reply, data };
      }
    };
    const next = queue.then(run, run);
    queue = next.catch(() => undefined);
    return next;
  };
  const deleted = async (form: string): Promise<number> => {
    const { reply, data } = await post('delete.php', 'application/x-www-form-urlencoded', encoder.encode(form));
    if (!reply.ok) throw failed(reply);
    return typeof data['deleted'] === 'number' ? data['deleted'] : 0;
  };
  return {
    async upload(bundle) {
      const { reply, data } = await post('notes.php', 'application/octet-stream', bundle);
      const id = data['id'];
      if (reply.status === 201 && typeof id === 'string' && NOTE_ID.test(id)) return { kind: 'sent', id };
      const error = data['error'];
      if (!reply.ok && typeof error === 'string' && (REFUSED_REASONS as readonly string[]).includes(error)) {
        const room = data['room'];
        return error === 'over_quota' && typeof room === 'number' && Number.isInteger(room) && room >= 0
          ? { kind: 'refused', reason: 'over_quota', room }
          : { kind: 'refused', reason: error as RefusedReason };
      }
      throw failed(reply);
    },
    async list() {
      const { reply, data } = await get('notes.php');
      if (!reply.ok) throw failed(reply);
      const notes = data['notes'];
      if (!Array.isArray(notes)) throw new UnreadableAnswer();
      const readable = notes.filter(isServerNote);
      return { notes: readable, unreadable: notes.length - readable.length };
    },
    async bytes(id) {
      const reply = await fetch(`note.php?id=${noteId(id)}`);
      if (reply.redirected || reply.status === 401 || reply.status === 403) throw new SignedOut('Your sign-in ended.');
      if (!reply.ok) throw failed(reply);
      if (!(reply.headers.get('content-type') ?? '').toLowerCase().startsWith('application/octet-stream')) throw new Error('note.php did not answer application/octet-stream.');
      return new Uint8Array(await reply.arrayBuffer());
    },
    remove: async id => deleted(`id=${noteId(id)}`),
    removeAll: async () => deleted('all=1'),
    async keyring() {
      const { reply, data } = await get('keyring.php');
      if (reply.status === 404 && data['error'] === 'no_keyring') throw new NoKeyring('No notes key has been uploaded yet.');
      const keyring = data['keyring'];
      if (!reply.ok) throw failed(reply);
      if (typeof keyring !== 'object' || keyring === null) throw new UnreadableAnswer();
      const ai = Array.isArray(data['ai']) ? data['ai'].filter((f): f is string => typeof f === 'string' && /^[0-9a-f]{64}$/.test(f)) : [];
      return { locked: keyring as LockedKeyring, session: typeof data['session'] === 'string' ? data['session'] : '', ai };
    },
    async uploadKeyring(locked, current) {
      const { reply, data } = await post('keyring.php', 'application/json', encoder.encode(JSON.stringify({ keyring: locked, current, previous: [] })));
      if (reply.status === 409 && data['error'] === 'key_exists') throw new KeyExists('This studio has a notes key already.');
      if (!reply.ok) throw failed(reply);
    },
    async changeKeyring(locked, current, previous, proof) {
      const { reply, data } = await post('keyring.php?change=1', 'application/json', encoder.encode(JSON.stringify({ keyring: locked, current, previous, proof })));
      if (reply.status === 409 && data['error'] === 'key_changed') throw new KeyChanged('The notes key on the server changed.');
      if (reply.status === 404 && data['error'] === 'no_keyring') throw new NoKeyring('No notes key has been uploaded yet.');
      if (!reply.ok) throw failed(reply);
    },
    async checkPairing(key, code) {
      const { reply, data } = await post('pair.php', 'application/json', encoder.encode(JSON.stringify({ key, code })));
      const refused = PAIR_REFUSALS.find(r => r === data['error']);
      if (!reply.ok && refused !== undefined) return refused;
      if (!reply.ok) throw failed(reply);
      if (typeof data['spki'] !== 'string' || typeof data['fingerprint'] !== 'string') throw new UnreadableAnswer();
      return { spki: data['spki'], fingerprint: data['fingerprint'] };
    },
    async pairKeyring(locked, current, previous, proof, pair) {
      const { reply, data } = await post('keyring.php?pair=1', 'application/json', encoder.encode(JSON.stringify({ keyring: locked, current, previous, proof, pair })));
      if (reply.status === 404 && data['error'] === 'no_keyring') throw new NoKeyring('No notes key has been uploaded yet.');
      const refused = PAIR_REFUSALS.find(r => r === data['error']);
      if (!reply.ok && refused !== undefined) return refused;
      if (!reply.ok) throw failed(reply);
      return null;
    },
    async deleteDraft(piece, version) {
      const form = `piece=${encodeURIComponent(piece)}${version === undefined ? '' : `&v=${version}`}`;
      const { reply, data } = await post('delete-draft.php', 'application/x-www-form-urlencoded', encoder.encode(form));
      if (!reply.ok) throw failed(reply);
      return typeof data['deleted'] === 'number' ? data['deleted'] : 0;
    },
  };
}
